MODULES.WeatherFx = function()
	-- WeatherFx (ModuleScript)
	-- Blends the sky between a clear Florida afternoon and a storm by the scenario's cloud cover.
	local Lighting = game:GetService("Lighting")
	local ServerStorage = game:GetService("ServerStorage")
	local TweenService = game:GetService("TweenService")

	local WeatherFx = {}

	local function ensure(parent, class, name)
		local x = parent:FindFirstChild(name)
		if not x then
			x = Instance.new(class)
			x.Name = name
			x.Parent = parent
		end
		return x
	end

	local targets = {
		lighting = Lighting,
		atmosphere = ensure(Lighting, "Atmosphere", "Atmosphere"),
		grade = ensure(Lighting, "ColorCorrectionEffect", "Grade"),
		clouds = ensure(workspace.Terrain, "Clouds", "Clouds"),
	}

	local CLEAR = {
		lighting = { ClockTime = 15, Brightness = 2.5, OutdoorAmbient = Color3.fromRGB(140, 140, 150) },
		atmosphere = { Density = 0.34, Haze = 1.6, Glare = 0.25, Color = Color3.fromRGB(196, 198, 172), Decay = Color3.fromRGB(96, 112, 96) },
		grade = { Brightness = 0, Contrast = 0.05, Saturation = 0.1, TintColor = Color3.new(1, 1, 1) },
		clouds = { Cover = 0.45, Density = 0.6, Color = Color3.new(1, 1, 1) },
	}
	local STORM = {
		lighting = { ClockTime = 17.2, Brightness = 1.2, OutdoorAmbient = Color3.fromRGB(90, 95, 110) },
		atmosphere = { Density = 0.55, Haze = 2.5, Glare = 0, Color = Color3.fromRGB(110, 115, 125), Decay = Color3.fromRGB(70, 75, 90) },
		grade = { Brightness = -0.05, Contrast = 0.12, Saturation = -0.25, TintColor = Color3.fromRGB(215, 225, 240) },
		clouds = { Cover = 0.95, Density = 0.85, Color = Color3.fromRGB(120, 125, 135) },
	}

	-- k = 0 is CLEAR, k = 1 is STORM
	local function blend(k)
		local out = {}
		for key, props in pairs(CLEAR) do
			out[key] = {}
			for name, a in pairs(props) do
				local b = STORM[key][name]
				out[key][name] = typeof(a) == "Color3" and a:Lerp(b, k) or a + (b - a) * k
			end
		end
		return out
	end

	local function set(preset, seconds)
		for key, props in pairs(preset) do
			if seconds > 0 then
				TweenService:Create(targets[key], TweenInfo.new(seconds, Enum.EasingStyle.Sine), props):Play()
			else
				for name, v in pairs(props) do targets[key][name] = v end
			end
		end
	end

	local function emitter()
		local part = workspace:FindFirstChild("RainEmitter")
		return part and part:FindFirstChildOfClass("ParticleEmitter")
	end

	-- The flood. FloodWater is a site wide plane that sits under the ground until a water event raises it.
	-- The scenarios speak in depth_mm (the contract); the twin exaggerates so the rise reads on screen:
	-- 20 mm is shin deep on the pad (gauge about 1 ft), 60 mm thigh deep (3 ft), 100 mm chest deep (4.7 ft).
	local WATER_Y = -0.5
	local STUDS_PER_MM = 2.4 / 60
	local RISE_SECONDS = 8

	function WeatherFx.setWater(depth_mm, instant)
		local top = depth_mm > 0 and math.min(6, 0.3 + depth_mm * STUDS_PER_MM) or -1
		workspace:SetAttribute("WaterSurface", math.max(WATER_Y, top)) -- Wildlife floats the boat, logs, pads, and gators to this
		local water = workspace:FindFirstChild("FloodWater")
		if not water then return end
		local goal = {
			Transparency = depth_mm > 0 and 0.28 or 1,
			CFrame = CFrame.new(water.CFrame.Position.X, top - water.Size.Y / 2, water.CFrame.Position.Z),
		}
		if instant then
			for name, v in pairs(goal) do water[name] = v end
		else
			TweenService:Create(water, TweenInfo.new(RISE_SECONDS, Enum.EasingStyle.Sine), goal):Play()
		end
	end

	function WeatherFx.reset()
		set(blend(0), 0)
		workspace:SetAttribute("Storm", 0)
		workspace.GlobalWind = Vector3.new(4, 0, 0)
		local e = emitter()
		if e then e.Enabled, e.Rate = false, 0 end
		WeatherFx.setWater(0, true)
		local gator = workspace:FindFirstChild("Gator")
		if gator then gator:Destroy() end
	end

	function WeatherFx.apply(e)
		local k = math.clamp(((e.clouds or 0) - 0.2) / 0.6, 0, 1)
		set(blend(k), 4)
		workspace:SetAttribute("Storm", k) -- Wildlife flushes the egrets past 0.6
		-- wind from the scenario's gust (mph), blowing east off the storm: bends the rain, the grass, and the clouds
		workspace.GlobalWind = Vector3.new(math.max(4, (e.gust or 0) * 0.8), 0, (e.gust or 0) * 0.15)
		local rain = emitter()
		if rain then
			rain.Enabled = (e.rain or 0) > 0
			rain.Rate = math.clamp((e.rain or 0) * 8, 0, 500)
		end
	end

	function WeatherFx.spawnGator()
		if workspace:FindFirstChild("Gator") then return end
		local template = ServerStorage:FindFirstChild("Gator")
		local spot = workspace:FindFirstChild("GatorSpot")
		if template and spot then
			local g = template:Clone()
			g:PivotTo(spot.CFrame)
			g.Parent = workspace
		end
	end

	return WeatherFx

end

MODULES.Lightning = function()
	-- Lightning (ModuleScript)
	local Debris = game:GetService("Debris")
	local Lighting = game:GetService("Lighting")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local TweenService = game:GetService("TweenService")

	local events = ReplicatedStorage:WaitForChild("SimEvents")
	local flashEvent = ReplicatedStorage:WaitForChild("FlashEvent")

	local Lightning = {}
	Lightning.STUDS_PER_MILE = 400
	local CLOUD_HEIGHT = 900
	local BOLT_COLOR = Color3.fromRGB(225, 235, 255)
	local BASE_EXPOSURE = Lighting.ExposureCompensation
	local rng = Random.new()

	local function origin()
		return workspace.Beacon:GetPivot().Position
	end

	-- bearing 0 is north (negative Z), 90 is east (positive X)
	function Lightning.groundPoint(bearing, miles)
		local o = origin()
		local r = miles * Lightning.STUDS_PER_MILE
		local x = o.X + math.sin(math.rad(bearing)) * r
		local z = o.Z - math.cos(math.rad(bearing)) * r
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { workspace.Beacon }
		local hit = workspace:Raycast(Vector3.new(x, 2000, z), Vector3.new(0, -4000, 0), params)
		return hit and hit.Position or Vector3.new(x, 0, z)
	end

	function Lightning.fromPosition(pos)
		local o = origin()
		local dx, dz = pos.X - o.X, pos.Z - o.Z
		local miles = math.sqrt(dx * dx + dz * dz) / Lightning.STUDS_PER_MILE
		local bearing = (math.deg(math.atan2(dx, -dz)) + 360) % 360
		return bearing, miles
	end

	local function segment(a, b, width, parts)
		local p = Instance.new("Part")
		p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
		p.Material = Enum.Material.Neon
		p.Color = BOLT_COLOR
		p.Size = Vector3.new(width, width, (b - a).Magnitude)
		p.CFrame = CFrame.lookAt((a + b) / 2, b)
		p.Name = "Bolt"
		p.Parent = workspace
		table.insert(parts, p)
	end

	-- jagged channel from a to b that thins toward b
	local function channel(a, b, width, steps, jitter, parts)
		local points = { a }
		for i = 1, steps - 1 do
			local base = a:Lerp(b, i / steps)
			table.insert(points, base + Vector3.new(rng:NextNumber(-jitter, jitter), 0, rng:NextNumber(-jitter, jitter)))
		end
		table.insert(points, b)
		for i = 1, #points - 1 do
			segment(points[i], points[i + 1], width * (1 - 0.4 * i / #points), parts)
		end
		return points
	end

	function Lightning.strike(bearing, miles)
		local ground = Lightning.groundPoint(bearing, miles)
		local top = Vector3.new(ground.X, CLOUD_HEIGHT, ground.Z)
		local width = math.max(3, miles * 0.8)
		local parts = {}

		-- 1. draw the bolt, a main channel and two thinner branches
		local main = channel(top, ground, width, rng:NextInteger(7, 9), 70, parts)
		local impact = parts[#main - 1]
		for _ = 1, 2 do
			local from = main[rng:NextInteger(2, #main - 2)]
			local drop = (from.Y - ground.Y) * rng:NextNumber(0.25, 0.45)
			local to = from + Vector3.new(rng:NextNumber(-160, 160), -drop, rng:NextNumber(-160, 160))
			channel(from, to, width * 0.45, 3, 40, parts)
		end
		local light = Instance.new("PointLight")
		light.Brightness, light.Range, light.Color = 20, 60, BOLT_COLOR
		light.Parent = impact
		Lighting.ExposureCompensation = BASE_EXPOSURE + 1.5

		-- 2. physical path: every client flashes white and schedules thunder
		flashEvent:FireAllClients(miles)

		-- 3. data path: the Bridge posts the strike
		events.Strike:Fire(bearing, miles)

		-- a return stroke flickers once, then the channel fades. Nothing here yields.
		local function setAll(t)
			for _, p in ipairs(parts) do p.Transparency = t end
		end
		task.delay(0.05, setAll, 1)
		task.delay(0.09, setAll, 0)
		task.delay(0.14, function()
			Lighting.ExposureCompensation = BASE_EXPOSURE
			for _, p in ipairs(parts) do
				TweenService:Create(p, TweenInfo.new(0.35), { Transparency = 1 }):Play()
				Debris:AddItem(p, 0.4)
			end
		end)
		print(("[Lightning] strike bearing %d miles %.1f"):format(bearing, miles))
	end

	return Lightning

end

MODULES.ScenarioEngine = function()
	-- ScenarioEngine (ModuleScript)
	local RunService = game:GetService("RunService")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local Scenarios = req("Scenarios")
	local Lightning = req("Lightning")
	local WeatherFx = req("WeatherFx")
	local events = ReplicatedStorage:WaitForChild("SimEvents")

	local Engine = {}
	Engine.Changed = Instance.new("BindableEvent")

	local state = {
		scenario = nil, key = nil, name = "", clockStart = "13:00",
		simTime = 0, speed = 60, playing = false, fired = {}, note = "",
	}

	function Engine.snapshot()
		return {
			key = state.key, name = state.name, clockStart = state.clockStart,
			simTime = state.simTime, speed = state.speed, playing = state.playing, note = state.note,
		}
	end

	local function emit()
		Engine.Changed:Fire(Engine.snapshot())
	end

	function Engine.load(key)
		local sc = Scenarios[key]
		if not sc then warn("[Engine] unknown scenario " .. tostring(key)) return end
		state.scenario, state.key, state.name = sc, key, sc.name
		state.clockStart = sc.clockStart or "13:00"
		state.simTime, state.speed, state.playing = 0, sc.speed or 60, false
		state.fired, state.note = {}, ""
		WeatherFx.reset()
		emit()
	end

	function Engine.play()
		if state.scenario then state.playing = true emit() end
	end

	function Engine.pause()
		state.playing = false
		emit()
	end

	function Engine.setSpeed(s)
		state.speed = math.clamp(s, 1, 600)
		emit()
	end

	local function dispatch(e)
		if e.type == "strike" then
			Lightning.strike(e.bearing, e.miles)
		elseif e.type == "weather" then
			WeatherFx.apply(e)
			events.Weather:Fire({ temp_c = e.temp_c, humidity = e.humidity, precip_mm = e.rain or 0, gust = e.gust })
		elseif e.type == "water" then
			WeatherFx.setWater(e.depth_mm)
			events.Water:Fire(e.depth_mm)
		elseif e.type == "wildlife" then
			WeatherFx.spawnGator()
		elseif e.type == "note" then
			state.note = e.text
			emit()
		end
		print(("[Engine] t=%d %s"):format(e.t, e.type))
	end

	local acc = 0
	RunService.Heartbeat:Connect(function(dt)
		if not state.playing or not state.scenario then return end
		state.simTime += dt * state.speed
		for i, e in ipairs(state.scenario.events) do
			if not state.fired[i] and e.t <= state.simTime then
				state.fired[i] = true
				dispatch(e)
			end
		end
		acc += dt
		if acc >= 0.5 then
			acc = 0
			emit()
		end
	end)

	return Engine

end

MODULES.SceneBuilder = function()
	-- SceneBuilder (ModuleScript in ServerScriptService/World)
	-- Builds the whole jobsite from code: a Florida swamp edge with cypress, moss, reeds, lily pads,
	-- alligators and egrets, plus the beacon, the work zone, equipment, poles, and every instance the World scripts look up by name (simulator guide 2.2).
	-- Run it once in edit mode from the Command Bar, then save and publish:
	--   require(game.ServerScriptService.World.SceneBuilder).build()
	-- Re-running wipes the terrain and everything named in OWNED, then rebuilds it the same way.
	-- Nothing is uploaded; every part is a plain Part.

	local Lighting = game:GetService("Lighting")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local ServerStorage = game:GetService("ServerStorage")

	local WeatherFx = req("WeatherFx")

	local Builder = {}

	local OWNED = { "Site", "Beacon", "ZonePart", "SiteBillboard", "Excavator", "RainEmitter", "GatorSpot", "FloodWater", "SpawnLocation", "Baseplate" }
	local SITE_NAME = "CRYSTAL RIVER"
	local ZONE = 60 -- work zone is ZONE x ZONE studs, centered on the beacon at the origin
	-- open water of the swamp east and south of the site, { center, radius }
	local SWAMP = {
		{ Vector3.new(150, 0, -60), 70 }, { Vector3.new(205, 0, 45), 85 }, { Vector3.new(170, 0, 150), 60 },
		{ Vector3.new(265, 0, -150), 75 }, { Vector3.new(40, 0, -235), 50 },
	}
	local WATER_Y = -0.5 -- water surface

	local C = {
		steel = Color3.fromRGB(78, 82, 90),
		concrete = Color3.fromRGB(168, 165, 158),
		dark = Color3.fromRGB(32, 34, 40),
		black = Color3.fromRGB(10, 10, 12),
		panel = Color3.fromRGB(18, 20, 26),
		safety = Color3.fromRGB(255, 184, 28),
		orange = Color3.fromRGB(240, 110, 30),
		white = Color3.fromRGB(236, 236, 230),
		green = Color3.fromRGB(40, 210, 100),
		yellow = Color3.fromRGB(255, 190, 0),
		red = Color3.fromRGB(235, 40, 40),
		dim = Color3.fromRGB(150, 155, 165),
		glass = Color3.fromRGB(140, 175, 195),
		tire = Color3.fromRGB(26, 26, 28),
		wood = Color3.fromRGB(105, 82, 60),
		bark = Color3.fromRGB(88, 70, 54),
		lcd = Color3.fromRGB(130, 200, 60),
		lcdText = Color3.fromRGB(20, 40, 10),
		leaves = { Color3.fromRGB(62, 96, 56), Color3.fromRGB(74, 108, 60), Color3.fromRGB(56, 86, 62) },
		moss = Color3.fromRGB(128, 138, 108),
		pine = Color3.fromRGB(48, 78, 46),
		pineBark = Color3.fromRGB(96, 72, 54),
		lily = Color3.fromRGB(72, 112, 48),
		reed = Color3.fromRGB(118, 138, 70),
		cattail = Color3.fromRGB(95, 62, 38),
		gator = Color3.fromRGB(50, 56, 38),
		gatorBelly = Color3.fromRGB(150, 140, 100),
		gatorEye = Color3.fromRGB(230, 200, 60),
		alum = Color3.fromRGB(150, 155, 160),
	}

	local rng
	local floating -- Site.Floating: lily pads, logs, the boat. Wildlife lifts them as the water rises.

	---------------------------------------------------------------- helpers

	local function part(parent, name, size, cf, color, material, shape)
		local p = Instance.new("Part")
		p.Name = name
		if shape then p.Shape = shape end
		p.Size, p.CFrame, p.Color = size, cf, color
		p.Material = material or Enum.Material.SmoothPlastic
		p.Anchored = true
		p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	local function ghost(p)
		p.Transparency, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = 1, false, false, false, false
		return p
	end

	-- vertical cylinder standing on pos
	local function column(parent, name, height, diameter, pos, color, material)
		return part(parent, name, Vector3.new(height, diameter, diameter),
			CFrame.new(pos + Vector3.new(0, height / 2, 0)) * CFrame.Angles(0, 0, math.rad(90)),
			color, material, Enum.PartType.Cylinder)
	end

	-- block from a to b
	local function strut(parent, name, a, b, width, color)
		return part(parent, name, Vector3.new(width, width, (b - a).Magnitude), CFrame.lookAt((a + b) / 2, b), color)
	end

	local function model(parent, name)
		local m = Instance.new("Model")
		m.Name = name
		m.Parent = parent
		return m
	end

	local function ensure(parent, class, name)
		local x = parent:FindFirstChild(name)
		if not x then
			x = Instance.new(class)
			x.Name = name
			x.Parent = parent
		end
		return x
	end

	-- every sign in the site faces +Z, toward the spawn
	local function surface(p, ppu)
		local g = Instance.new("SurfaceGui")
		g.Face = Enum.NormalId.Back
		g.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
		g.PixelsPerStud = ppu or 60
		g.LightInfluence = 0
		g.Parent = p
		return g
	end

	local function label(parent, name, text, size, pos, color, font, bg)
		local t = Instance.new("TextLabel")
		t.Name, t.Text, t.Size, t.Position = name, text, size, pos
		t.TextColor3, t.Font, t.TextScaled = color, font or Enum.Font.GothamBold, true
		t.BorderSizePixel = 0
		t.BackgroundTransparency = bg and 0 or 1
		if bg then t.BackgroundColor3 = bg end
		t.Parent = parent
		return t
	end

	---------------------------------------------------------------- pieces

	local function plumbing()
		local sim = ensure(ReplicatedStorage, "Folder", "SimEvents")
		for _, n in ipairs({ "Strike", "Weather", "Water", "PresenceChanged" }) do
			ensure(sim, "BindableEvent", n)
		end
		for _, n in ipairs({ "FlashEvent", "ScenarioControl", "ScenarioState", "StrikeHere" }) do
			ensure(ReplicatedStorage, "RemoteEvent", n)
		end
		local thunder = ensure(ReplicatedStorage, "Sound", "Thunder")
		if thunder.SoundId == "" then
			warn("[SceneBuilder] set ReplicatedStorage.Thunder.SoundId from a Toolbox thunder clip")
		end
	end

	local function terrain()
		local T = workspace.Terrain
		T:Clear()
		T:FillBlock(CFrame.new(0, -8, 0), Vector3.new(2048, 16, 2048), Enum.Material.Grass)
		T:FillBlock(CFrame.new(-620, -8, 0), Vector3.new(800, 16, 2048), Enum.Material.LeafyGrass) -- dry pine flatwoods west
		for _, s in ipairs(SWAMP) do
			local c, r = s[1], s[2]
			T:FillCylinder(CFrame.new(c.X, -8, c.Z), 16, r + 16, Enum.Material.Mud) -- muddy bank
			T:FillCylinder(CFrame.new(c.X, -3, c.Z), 6, r, Enum.Material.Air)
			T:FillCylinder(CFrame.new(c.X, -3.25, c.Z), 5.5, r, Enum.Material.Water)
		end
		T:FillBlock(CFrame.new(0, -8, 0), Vector3.new(112, 16, 112), Enum.Material.Ground) -- work pad, stays dry
		T:FillBlock(CFrame.new(0, -8, 520), Vector3.new(28, 16, 930), Enum.Material.Mud) -- access road
		pcall(function() T.Decoration = true end) -- swaying grass; not scriptable in every Studio, tick Terrain > Decoration by hand
		T.WaterColor = Color3.fromRGB(52, 66, 40)
		T.WaterTransparency, T.WaterReflectance = 0.7, 0.35
		T.WaterWaveSize, T.WaterWaveSpeed = 0.03, 3
		T:SetMaterialColor(Enum.Material.Grass, Color3.fromRGB(92, 120, 58))
		T:SetMaterialColor(Enum.Material.LeafyGrass, Color3.fromRGB(110, 118, 64))
		T:SetMaterialColor(Enum.Material.Ground, Color3.fromRGB(132, 116, 88))
		T:SetMaterialColor(Enum.Material.Mud, Color3.fromRGB(78, 64, 46))
	end

