		up.PrimaryPart = ghost(part(up, "Hub", Vector3.new(1, 1, 1), cf * CFrame.new(0, 2.6, 0), C.steel))
		part(up, "Body", Vector3.new(6.5, 2.8, 7), cf * CFrame.new(0, 3.6, 0.8), C.safety)
