		part(up, "CabRoof", Vector3.new(3, 0.3, 3.2), cf * CFrame.new(-1.8, 8.1, -1.2), C.safety)
		strut(up, "Boom", P(1.4, 4.8, -1.8), P(1.4, 9.6, -9.4), 1.2, C.safety)
		strut(up, "Stick", P(1.4, 9.6, -9.4), P(1.4, 3.4, -10.6), 0.9, C.safety)
